    var ext: [String: Any] = [:]
    let configKey = codec == kCMVideoCodecType_AV1 ? "av1C" : "vpcC"
    guard let config = atoms[configKey] else { print("no \(configKey) in source"); exit(1) }
    ext[kCMFormatDescriptionExtension_SampleDescriptionExtensionAtoms as String] = [configKey: config]
    switch colour {
    case "hlg", "pq":
        ext[kCMFormatDescriptionExtension_ColorPrimaries as String] =
            kCMFormatDescriptionColorPrimaries_ITU_R_2020
        ext[kCMFormatDescriptionExtension_TransferFunction as String] = colour == "pq"
            ? REDACTED
            : REDACTED
        ext[kCMFormatDescriptionExtension_YCbCrMatrix as String] =
            REDACTED
        if colour == "pq" {
            // HD-5's fixed HDR10: P3-D65 mastering display 0.005–1000 cd/m²,
            // MaxCLL 1000, MaxFALL 0 (SMPTE ST 2086 / CTA-861.3 big-endian blobs).
            var mdcv = Data()
            func be16(_ v: UInt16) { mdcv.append(UInt8(v >> 8)); mdcv.append(UInt8(v & 0xff)) }
            func be32(_ v: UInt32) { for s in [24, 16, 8, 0] { mdcv.append(UInt8((v >> UInt32(s)) & 0xff)) } }
            // G, B, R primaries then white point, in 0.00002 units (P3-D65)
            for (x, y) in [(13250, 34500), (7500, 3000), (34000, 16000)] { be16(UInt16(x)); be16(UInt16(y)) }
            be16(15635); be16(16450)
            be32(10_000_000); be32(50)  // max / min luminance in 0.0001 cd/m²
            ext[kCMFormatDescriptionExtension_MasteringDisplayColorVolume as String] = mdcv
            ext[kCMFormatDescriptionExtension_ContentLightLevelInfo as String] =
                Data([0x03, 0xe8, 0x00, 0x00])
        }
    case "sdr":
        u.hlgOutput = hlg
        return u
    }

    /// An encoded canvas's block: only an HLG canvas whose key asked for the
    /// SDR version or PQ.
    private static func encodedUniforms(for canvas: RecipeCanvas) -> OutputUniforms? {
        guard canvas.output == .hlg else { return nil }
        switch canvas.dynamicRange {
        case .sdr: return OutputUniforms(mode: 1, knee: sdrKnee)
        case .pq: return OutputUniforms(mode: 2, knee: sdrKnee)
        case .hlg, nil: return nil
        }
    }

    /// HDR10's mastering display (HD-5, HD-14 (d)), SMPTE ST 2086 in the order
    /// H.265's SEI 137 carries it: P3's green, blue and red primaries and D65
    /// as x, y in 0.00002, then the maximum (1,000 cd/m²) and minimum (0.005
    /// cd/m²) luminance in 0.0001, big-endian.
    static let masteringDisplay = Data([
        0x33, 0xC2, 0x86, 0xC4, 0x1D, 0x4C, 0x0B, 0xB8, 0x84, 0xD0, 0x3E, 0x80,
        0x3D, 0x13, 0x40, 0x42, 0x00, 0x98, 0x96, 0x80, 0x00, 0x00, 0x00, 0x32,
    ])

    /// HDR10's content light level (CTA-861.3): MaxCLL 1,000 cd/m², MaxFALL
    /// 0 ("unknown"), big-endian.
    static let contentLightLevel = Data([0x03, 0xE8, 0x00, 0x00])
}
