        file_type: "com.apple.quicktime-movie",
        avf_preset: Some("AVAssetExportPresetHEVCHighestQualityWithAlpha"),
    },
    // HEVC Main 10 (spec §11 PR-3): `hevc`'s MP4 in every field but the
    // id and the codec, after `hevc_alpha` (G-33 keeps that one directly
    // after `hevc`). The 10 bits are the writer's profile, not a field.
    Expected {
        id: "hevc_10bit",
        container: "mp4",
        codec: "hevc_10bit",
        size: None,
        fps: None,
        video: true,
        audio: true,
        alpha: false,
        file_type: "public.mpeg-4",
        avf_preset: Some("AVAssetExportPresetHEVCHighestQuality"),
    },
    // AV1 in MP4 (spec §11 CX-12): SVT-AV1 encodes and AVFoundation writes
    // the MP4, so it is an AVFoundation row whose session name is the
    // passthrough one, a record only.
    Expected {
        id: "av1",
        container: "mp4",
        codec: "av1",
        size: None,
        fps: None,
        video: true,
        audio: true,
        alpha: false,
        file_type: "public.mpeg-4",
        avf_preset: Some("AVAssetExportPresetPassthrough"),
    },
    Expected {
    let rows = preset_ids();
    assert!(rows.len() >= 11, "{rows:?}");
    for (id, video) in rows {
        let plain = sdr
            .export_settings(&id, None)
            .unwrap_or_else(|msg| panic!("{id} in an SDR project: {msg}"));
        assert!(plain.get("color").is_none(), "{id}: {plain}");
        let answer = hlg.export_settings(&id, None);
        if !video {
            assert_eq!(
                answer.as_ref(),
                Ok(&plain),
                "{id}: an audio row is unchanged"
            );
        } else if ["hevc_10bit", "prores_422", "prores_4444"].contains(&id.as_str()) {
            let mut want = plain.clone();
            want["color"] = json!("hlg");
            assert_eq!(answer, Ok(want), "{id}");
        } else {
            // H-3 (spec §11 HD-14): the SDR version, where H-2 refused.
            let mut want = plain.clone();
            want["color"] = json!("sdr");
            assert_eq!(answer, Ok(want), "{id}");
        }
    }
}

